changeSet.sql:
CREATE TABLE clinlims.lab_test_remarks (
    id           SERIAL PRIMARY KEY,
    entity_type  VARCHAR(10)   NOT NULL,
    entity_id    NUMERIC(10,0) NOT NULL,
    remarks      VARCHAR(2000),
    lastupdated  TIMESTAMP WITH TIME ZONE DEFAULT now(),
    sys_user_id  VARCHAR(255),
    CONSTRAINT uq_lab_test_remarks_entity UNIQUE (entity_type, entity_id)
);
COMMENT ON TABLE clinlims.lab_test_remarks IS 'Stores per-test/panel remarks for printed reports.';
COMMENT ON COLUMN clinlims.lab_test_remarks.entity_type IS 'TEST or PANEL';
COMMENT ON COLUMN clinlims.lab_test_remarks.entity_id IS 'PK of clinlims.test or clinlims.panel.';
